import{_ as l,r as a,o,c as i,e as n,a as p,s as c}from"./chunks/framework.CXcwiNg-.js";const g=JSON.parse('{"title":"Content Fields - October CMS - 4.x","titleTemplate":false,"description":"Get started by defining form fields for your content.","frontmatter":{"subtitle":"Get started by defining form fields for your content."},"headers":[{"level":2,"title":"List and Filter Properties","slug":"list-and-filter-properties","link":"#list-and-filter-properties","children":[{"level":3,"title":"Field Configuration","slug":"field-configuration","link":"#field-configuration","children":[]},{"level":3,"title":"External Configuration","slug":"external-configuration","link":"#external-configuration","children":[]}]},{"level":2,"title":"Form Field Validation","slug":"form-field-validation","link":"#form-field-validation","children":[]},{"level":2,"title":"Modifying Core Fields","slug":"modifying-core-fields","link":"#modifying-core-fields","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/cms/tailor/content-fields.md","filePath":"4.x/cms/tailor/content-fields.md"}'),r={name:"4.x/cms/tailor/content-fields.md"};function d(u,e,f,m,k,h){const s=a("pre-heading"),t=a("post-heading");return o(),i("div",null,[n(s),e[0]||(e[0]=p("h1",null,"Content Fields",-1)),n(t),e[1]||(e[1]=c(`<div class="custom-block aside"><p>You may build custom content fields by <a href="./../../extend/tailor-fields.html">extending tailor</a>.</p></div><p>Content Fields are the cornerstone of the Tailor module and define how a field should be configured and displayed. These definitions are often found under the <strong>fields</strong> property of a blueprint.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">name</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Full Name
        <span class="token key atrule">type</span><span class="token punctuation">:</span> text
</code></pre></div><div class="custom-block tip"><p>A complete list of available fields can be found in the <a href="./../../element/form-fields.html">Backend Elements section</a>.</p></div><p>For each field you can specify these common properties, where applicable.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>a name when displaying the form field to the user.</td></tr><tr><td><strong>shortLabel</strong></td><td>a shorter label to use in lists and filters.</td></tr><tr><td><strong>type</strong></td><td>defines how this field should be rendered, see <a href="./../../element/form-fields.html">form field definitions</a>. Default: text.</td></tr><tr><td><strong>span</strong></td><td>aligns the form field to one side. Options: auto, left, right, row, full, adaptive. Default: <code>full</code>.</td></tr><tr><td><strong>spanClass</strong></td><td>used with the span <code>row</code> option to display the form as a Bootstrap grid, for example, <code>spanClass: col-4</code>.</td></tr><tr><td><strong>size</strong></td><td>specifies a field size for fields that use it, for example, the textarea field.</td></tr><tr><td><strong>placeholder</strong></td><td>if the field supports a placeholder value.</td></tr><tr><td><strong>comment</strong></td><td>places a descriptive comment below the field.</td></tr><tr><td><strong>commentAbove</strong></td><td>places a comment above the field.</td></tr><tr><td><strong>commentHtml</strong></td><td>allow HTML markup inside the comment. Default: <code>false</code>.</td></tr><tr><td><strong>default</strong></td><td>specify the default value for the field. For <code>dropdown</code>, <code>checkboxlist</code>, <code>radio</code> and <code>balloon-selector</code> widgets, you may specify an option key here to have it selected by default.</td></tr><tr><td><strong>tab</strong></td><td>assigns the field to a tab.</td></tr><tr><td><strong>validation</strong></td><td>defines validation rules for the form field, see <a href="./../../extend/services/validation.html">the validation article</a> for rule definitions.</td></tr><tr><td><strong>trigger</strong></td><td>specify conditions for this field using <a href="./../../element/form-fields.html">trigger events</a>.</td></tr><tr><td><strong>preset</strong></td><td>allows the field value to be initially set by the value of another field, converted using the <a href="./../../element/form-fields.html">input preset converter</a>.</td></tr><tr><td><strong>translatable</strong></td><td>disables translation for this field when using the <code>multisite</code> in the blueprint definition. For repeater fields, set to <code>sync</code> to keep the repeater structure synced across sites while allowing sub-fields to be translated independently, see <a href="./../../element/form/widget-repeater.html">Translatable Repeaters</a>.</td></tr></tbody></table></div><h2 id="list-and-filter-properties"><a href="#list-and-filter-properties" class="header-anchor">#</a> List and Filter Properties</h2><p>When it comes to displaying a field in a list or filter, each field has its own default settings. You may override these settings on a per field basis and this is suitable for minor adjustments. For more complex use cases, we recommend defining columns and scopes separately from the fields (see below).</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>column</strong></td><td>defines how to display the field in a list, see <a href="./../../element/list-columns.html">list column definitions</a>.</td></tr><tr><td><strong>scope</strong></td><td>defines how to display the field in a filter, see <a href="./../../element/filter-scopes.html">filter scope definitions</a>.</td></tr></tbody></table></div><h3 id="field-configuration"><a href="#field-configuration" class="header-anchor">#</a> Field Configuration</h3><p>An example can be specifying a different label for each using the <code>column</code> or <code>scope</code> properties of the field.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">myfield</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Form Label
    <span class="token key atrule">column</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> List Label
    <span class="token key atrule">scope</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Filter Label
</code></pre></div><p>If the are set to <code>false</code> then the field will disable and prevent it from being displayed.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">myfield</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Form Label
    <span class="token key atrule">column</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
    <span class="token key atrule">scope</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><p>The <code>column</code> type can be set to <code>invisible</code> to make it hidden from the list by default.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">myfield</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Form Label
    <span class="token key atrule">column</span><span class="token punctuation">:</span> invisible
</code></pre></div><h3 id="external-configuration"><a href="#external-configuration" class="header-anchor">#</a> External Configuration</h3><p>You may define the scopes and columns separately from the form fields by using the <code>columns</code> and <code>scopes</code> property in the blueprint. When using external configuration, the default view will be replaced by only the defined fields.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">scopes</span><span class="token punctuation">:</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Filter Label
        <span class="token comment"># [...]</span>

<span class="token key atrule">columns</span><span class="token punctuation">:</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> List Label
        <span class="token comment"># [...]</span>

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Form Label
        <span class="token comment"># [...]</span>
</code></pre></div><div class="custom-block tip"><p>A <strong>fields</strong> definition must exist for a <strong>columns</strong> or <strong>scopes</strong> definition to be valid. To hide the definition from the form, use <code>hidden: true</code> to hide it from the form, and then <code>hidden: false</code> to display it in the column or scope.</p></div><p>List columns have short-hand values that can be used. Passing a string will replace the label, passing <code>true</code> will include the default column, passing <code>false</code> will remove the column and passing <code>invisible</code> will make the column invisible.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">columns</span><span class="token punctuation">:</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span> List Label   <span class="token comment"># New Label</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>         <span class="token comment"># Shown</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>        <span class="token comment"># Hidden</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span> invisible    <span class="token comment"># Invisible</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">...</span><span class="token punctuation">]</span>        <span class="token comment"># Config Array</span>
</code></pre></div><p>Filter scopes have a similar short-hand values to the list columns that can be used.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">scopes</span><span class="token punctuation">:</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span> Filter Label <span class="token comment"># New Label</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>         <span class="token comment"># Shown</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>        <span class="token comment"># Hidden</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">...</span><span class="token punctuation">]</span>        <span class="token comment"># Config Array</span>
</code></pre></div><h2 id="form-field-validation"><a href="#form-field-validation" class="header-anchor">#</a> Form Field Validation</h2><p>You may specify validation rules for form fields using the <code>validation</code> field property, see <a href="./../../extend/services/validation.html">the validation article</a> for rule definitions.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Featured Text
        <span class="token key atrule">validation</span><span class="token punctuation">:</span> <span class="token string">&quot;required|min:15&quot;</span>
</code></pre></div><p>Validation rules can also be defined externally in the blueprint file using the <code>validation</code> blueprint property. This allows you to set custom attribute names and validation messages.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">validation</span><span class="token punctuation">:</span>
    <span class="token key atrule">rules</span><span class="token punctuation">:</span>
        <span class="token key atrule">myfield</span><span class="token punctuation">:</span> <span class="token string">&quot;required|min:15&quot;</span>
    <span class="token key atrule">attributeNames</span><span class="token punctuation">:</span>
        <span class="token key atrule">myfield</span><span class="token punctuation">:</span> My Field
    <span class="token key atrule">customMessages</span><span class="token punctuation">:</span>
        <span class="token key atrule">myfield.min</span><span class="token punctuation">:</span> <span class="token string">&quot;My field has to be at least 15 characters long&quot;</span>

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Form Label
        <span class="token comment"># [...]</span>
</code></pre></div><p>The <code>unique</code> validation rule is automatically configured and does not require a table name to be specified.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">unique_field</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Unique Field
    <span class="token key atrule">validation</span><span class="token punctuation">:</span> unique
</code></pre></div><p>The <code>required</code> validation rule supports <strong>create</strong> and <strong>update</strong> modifiers to only apply when a model is created or updated respectively. The following is only required when the model does not already exist.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">password</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Password
    <span class="token key atrule">validation</span><span class="token punctuation">:</span> <span class="token string">&quot;required:create&quot;</span>
</code></pre></div><h2 id="modifying-core-fields"><a href="#modifying-core-fields" class="header-anchor">#</a> Modifying Core Fields</h2><p>Each blueprint record has several core fields as <a href="./models.html">defined by attributes on the model</a>. You can modify these fields under certain conditions.</p><p>An Entry is enabled by default; however, you can modify this by specifying a new default value for the <code>is_enabled</code> field.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">is_enabled</span><span class="token punctuation">:</span>
        <span class="token key atrule">default</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><p>The <code>title</code> field placeholder is generated based on the blueprint name; however, you can customize this to something more useful depending on the use case. For example, <em>First and Last Name</em>, <em>Event Title</em> or <em>Location Name</em>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span>
        <span class="token key atrule">placeholder</span><span class="token punctuation">:</span> Event Title
</code></pre></div><p>In some cases the <code>title</code> field may not be required, such as using a <a href="./blueprints.html">single blueprint</a>,you may set the <code>hidden</code> property to <code>true</code>. Hiding the title will disable the in-built validation for this field.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span>
        <span class="token key atrule">hidden</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../element/form-fields.html">Defining Form Fields</a></li><li><a href="./../../extend/tailor-fields.html">Building Tailor Fields</a></li></ul></div>`,43))])}const b=l(r,[["render",d]]);export{g as __pageData,b as default};
